-/**
- * @file test_geir_bn_infer_grad.cpp
- * @brief GE IR 图模式调用示例 - BNInferGrad (arch35)
- *
- * 数学公式: x_backprop = grads * scale * 1/sqrt(batch_variance + epsilon)
- *
- * 通过 GE Session 构建计算图，编译并执行 BNInferGrad 算子。
- */
-
-#include <iostream>
-#include <fstream>
-#include <string.h>
-#include <stdint.h>
-#include <vector>
-#include <string>
-#include <map>
-#include <cmath>
-#include "assert.h"
-
-#include "graph.h"
-#include "types.h"
-#include "tensor.h"
-#include "ge_error_codes.h"
-#include "ge_api_types.h"
-#include "ge_api.h"
-#include "array_ops.h"
-#include "ge_ir_build.h"
-
-#include "../../op_graph/bn_infer_grad_proto.h"
-
-#define FAILED -1
-#define SUCCESS 0
-
-using namespace ge;
-using std::map;
-using std::string;
-using std::vector;
-
-#define ADD_INPUT(inputIndex, inputName, inputDtype, inputFormat, inputShape)                                   \
-    vector<int64_t> placeholder##inputIndex##_shape = inputShape;                                               \
-    auto placeholder##inputIndex = op::Data("placeholder" #inputIndex).set_attr_index(inputIndex - 1);          \
-    TensorDesc placeholder##inputIndex##_desc =                                                                 \
-        TensorDesc(ge::Shape(placeholder##inputIndex##_shape), inputFormat, inputDtype);                        \
-    placeholder##inputIndex##_desc.SetPlacement(ge::kPlacementHost);                                            \
-    placeholder##inputIndex##_desc.SetFormat(inputFormat);                                                      \
-    Tensor tensor_placeholder##inputIndex;                                                                      \
-    ret = GenInputData(                                                                                         \
-        placeholder##inputIndex##_shape, tensor_placeholder##inputIndex, placeholder##inputIndex##_desc,        \
-        inputDtype, inputIndex);                                                                                \
-    if (ret != SUCCESS) {                                                                                       \
-        printf("%s - ERROR - [XIR]: Generate input data failed\n", GetTime().c_str());                          \
-        return FAILED;                                                                                          \
-    }                                                                                                           \
-    placeholder##inputIndex.update_input_desc_x(placeholder##inputIndex##_desc);                                \
-    input.push_back(tensor_placeholder##inputIndex);                                                            \
-    graph.AddOp(placeholder##inputIndex);                                                                       \
-    bnInferGradOp.set_input_##inputName(placeholder##inputIndex);                                               \
-    inputs.push_back(placeholder##inputIndex);
-
-#define ADD_OUTPUT(outputIndex, outputName, outputDtype, outputFormat, outputShape)                              \
-    TensorDesc outputName##outputIndex##_desc = TensorDesc(ge::Shape(outputShape), outputFormat, outputDtype);  \
-    bnInferGradOp.update_output_desc_##outputName(outputName##outputIndex##_desc);
-
-string GetTime()
-{
-    time_t timep;
-    time(&timep);
-    char tmp[64];
-    strftime(tmp, sizeof(tmp), "%Y-%m-%d %H:%M:%S,000", localtime(&timep));
-    return tmp;
-}
-
-uint32_t GetDataTypeSize(DataType dt)
-{
-    if (dt == ge::DT_FLOAT) {
-        return 4;
-    } else if (dt == ge::DT_FLOAT16 || dt == ge::DT_BF16) {
-        return 2;
-    }
-    return 4;
-}
-
-int32_t GenInputData(
-    vector<int64_t> shapes, Tensor& input_tensor, TensorDesc& input_tensor_desc, DataType data_type, int inputIndex)
-{
-    input_tensor_desc.SetRealDimCnt(shapes.size());
-    size_t size = 1;
-    for (uint32_t i = 0; i < shapes.size(); i++) {
-        size *= shapes[i];
-    }
-    uint32_t data_len = size * GetDataTypeSize(data_type);
-    float* pData = new (std::nothrow) float[size];
-    if (pData == nullptr) {
-        return FAILED;
-    }
-
-    if (inputIndex == 1) {
-        // grads: 全 1.0
-        for (size_t i = 0; i < size; ++i) {
-            pData[i] = 1.0f;
-        }
-    } else if (inputIndex == 2) {
-        // scale: 全 1.0 (gamma)
-        for (size_t i = 0; i < size; ++i) {
-            pData[i] = 1.0f;
-        }
-    } else {
-        // batch_variance: 单调递增（0.1, 0.2, ...）
-        for (size_t i = 0; i < size; ++i) {
-            pData[i] = 0.1f * static_cast<float>(i + 1);
-        }
-    }
-    input_tensor = Tensor(input_tensor_desc, reinterpret_cast<uint8_t*>(pData), data_len);
-    delete[] pData;
-    return SUCCESS;
-}
-
-int32_t WriteDataToFile(string bin_file, uint64_t data_size, uint8_t* inputData)
-{
-    FILE* fp = fopen(bin_file.c_str(), "w");
-    if (fp == nullptr) {
-        return FAILED;
-    }
-    fwrite(inputData, sizeof(uint8_t), data_size, fp);
-    fclose(fp);
-    return SUCCESS;
-}
-
-int CreateOppInGraph(
-    DataType inDtype, std::vector<ge::Tensor>& input, std::vector<Operator>& inputs, std::vector<Operator>& outputs,
-    Graph& graph)
-{
-    Status ret = SUCCESS;
-    // 创建 BNInferGrad 算子节点
-    auto bnInferGradOp = op::BNInferGrad("bn_infer_grad_1");
-
-    // NCHW 形式：N=2, C=4, H=4, W=4
-    std::vector<int64_t> gradsShape = {2, 4, 4, 4};
-    std::vector<int64_t> scaleShape = {4};
-    std::vector<int64_t> varianceShape = {4};
-
-    // 添加输入: grads(idx=1, NCHW), scale(idx=2, ND), batch_variance(idx=3, ND)
-    ADD_INPUT(1, grads, inDtype, FORMAT_NCHW, gradsShape);
-    ADD_INPUT(2, scale, DT_FLOAT, FORMAT_ND, scaleShape);
-    ADD_INPUT(3, batch_variance, DT_FLOAT, FORMAT_ND, varianceShape);
-
-    // 默认 epsilon = 0.0001
-    bnInferGradOp.set_attr_epsilon(0.0001f);
-
-    // 添加输出 x_backprop (NCHW)
-    ADD_OUTPUT(1, x_backprop, inDtype, FORMAT_NCHW, gradsShape);
-
-    outputs.push_back(bnInferGradOp);
-    return SUCCESS;
-}
-
-int main(int argc, char* argv[])
-{
-    const char* graph_name = "bn_infer_grad_ge_ir_test";
-    Graph graph(graph_name);
-    std::vector<ge::Tensor> input;
-
-    printf("%s - INFO - [XIR]: Start to initialize ge using ge global options\n", GetTime().c_str());
-    std::map<AscendString, AscendString> global_options = {{"ge.exec.deviceId", "0"}, {"ge.graphRunMode", "1"}};
-    Status ret = ge::GEInitialize(global_options);
-    if (ret != SUCCESS) {
-        printf("%s - ERROR - [XIR]: Initialize ge using ge global options failed\n", GetTime().c_str());
-        return FAILED;
-    }
-    printf("%s - INFO - [XIR]: Initialize ge using ge global options success\n", GetTime().c_str());
-
-    std::vector<Operator> inputs{};
-    std::vector<Operator> outputs{};
-
-    DataType inDtype = DT_FLOAT;
-    if (argc > 1) {
-        std::string dtypeArg(argv[1]);
-        if (dtypeArg == "fp16") {
-            inDtype = DT_FLOAT16;
-        } else if (dtypeArg == "bf16") {
-            inDtype = DT_BF16;
-        }
-    }
-    printf("%s - INFO - [XIR]: Using grads dtype = %d\n", GetTime().c_str(), static_cast<int>(inDtype));
-
-    ret = CreateOppInGraph(inDtype, input, inputs, outputs, graph);
-    if (ret != SUCCESS) {
-        printf("%s - ERROR - [XIR]: Create op in graph failed\n", GetTime().c_str());
-        return FAILED;
-    }
-
-    if (!inputs.empty() && !outputs.empty()) {
-        graph.SetInputs(inputs).SetOutputs(outputs);
-    }
-
-    std::map<AscendString, AscendString> build_options = {};
-    printf("%s - INFO - [XIR]: Start to create ir session using build options\n", GetTime().c_str());
-    ge::Session* session = new Session(build_options);
-
-    if (session == nullptr) {
-        printf("%s - ERROR - [XIR]: Create ir session using build options failed\n", GetTime().c_str());
-        return FAILED;
-    }
-    printf("%s - INFO - [XIR]: Create ir session using build options success\n", GetTime().c_str());
-    printf("%s - INFO - [XIR]: Start to add compute graph to ir session\n", GetTime().c_str());
-
-    std::map<AscendString, AscendString> graph_options = {};
-    uint32_t graph_id = 0;
-    ret = session->AddGraph(graph_id, graph, graph_options);
-    if (ret != SUCCESS) {
-        printf("%s - ERROR - [XIR]: Add graph to session failed\n", GetTime().c_str());
-        delete session;
-        GEFinalize();
-        return FAILED;
-    }
-
-    printf("%s - INFO - [XIR]: Session add ir compute graph to ir session success\n", GetTime().c_str());
-    printf("%s - INFO - [XIR]: Start to run ir compute graph\n", GetTime().c_str());
-    std::vector<ge::Tensor> output;
-    ret = session->RunGraph(graph_id, input, output);
-    if (ret != SUCCESS) {
-        printf("%s - ERROR - [XIR]: Run graph failed\n", GetTime().c_str());
-        delete session;
-        GEFinalize();
-        return FAILED;
-    }
-    printf("%s - INFO - [XIR]: Session run ir compute graph success\n", GetTime().c_str());
-
-    // 验证输出
-    int output_num = output.size();
-    printf("%s - INFO - [XIR]: Number of outputs: %d\n", GetTime().c_str(), output_num);
-    for (int i = 0; i < output_num; i++) {
-        int64_t output_shape = output[i].GetTensorDesc().GetShape().GetShapeSize();
-        printf("%s - INFO - [XIR]: output %d shape size = %ld, dtype = %d\n",
-               GetTime().c_str(), i, output_shape,
-               static_cast<int>(output[i].GetTensorDesc().GetDataType()));
-
-        if (output[i].GetTensorDesc().GetDataType() == DT_FLOAT && output_shape > 0) {
-            float* outData = reinterpret_cast<float*>(output[i].GetData());
-            int64_t printNum = (output_shape < 10) ? output_shape : 10;
-            // grads=1, scale=1, NCHW (N=2,C=4,H=4,W=4) → spatialSize=16
-            // 通道索引 c = (j / 16) % 4, batch_variance[c] = 0.1*(c+1)
-            // expected = 1 * 1 / sqrt(0.1*(c+1) + 0.0001)
-            for (int64_t j = 0; j < printNum; j++) {
-                int64_t c = (j / 16) % 4;
-                float bv = 0.1f * static_cast<float>(c + 1);
-                float expected = 1.0f / std::sqrt(bv + 0.0001f);
-                printf("  output[%ld] = %.6f (expected = %.6f)\n", j, outData[j], expected);
-            }
-        }
-    }
-
-    ge::AscendString error_msg = ge::GEGetErrorMsgV2();
-    std::string error_str(error_msg.GetString());
-    if (!error_str.empty()) {
-        std::cout << "Error message: " << error_str << std::endl;
-    }
-
-    printf("%s - INFO - [XIR]: Start to finalize ir graph session\n", GetTime().c_str());
-    delete session;
-    ret = ge::GEFinalize();
-    if (ret != SUCCESS) {
-        printf("%s - ERROR - [XIR]: Finalize ir graph session failed\n", GetTime().c_str());
-        return FAILED;
-    }
-    printf("%s - INFO - [XIR]: Finalize ir graph session success\n", GetTime().c_str());
-    return SUCCESS;
-}

